import os,re
root='AlgebraicJacobian'
mods={}
for dp,_,fns in os.walk(root):
    for fn in fns:
        if fn.endswith('.lean'): 
            p=os.path.join(dp,fn); mods[p[:-5].replace('/','.')]=p
imports={}; umbrella=set()
for n,p in mods.items():
    ds=[]
    for line in open(p,errors='replace'):
        m=re.match(r'^import\s+([A-Za-z0-9_.]+)',line)
        if m:
            d=m.group(1)
            if d=='Mathlib': umbrella.add(n)
            elif d.startswith('AlgebraicJacobian'): ds.append(d)
    imports[n]=ds
def clean_count(umb):
    memo={}
    def cont(m):
        if m in memo: return memo[m]
        memo[m]=True
        r = m in umb or any(cont(d) for d in imports.get(m,[]))
        memo[m]=r; return r
    return sum(1 for m in mods if not cont(m))
cur=set(umbrella)
base=clean_count(cur)
order=[]
while True:
    best=None
    for m in sorted(cur):
        gain=clean_count(cur-{m})-clean_count(cur)
        size=os.path.getsize(mods[m])
        score=(gain, -size)
        if best is None or score>best[0]: best=(score,m,gain,size)
    if best is None: break
    _,m,gain,size=best
    cur.discard(m); order.append((m,gain,size,clean_count(cur)))
    if not cur: break
print(f"# greedy de-umbrella order; baseline umbrella-free = {base}/{len(mods)}")
print(f"# {'module':70s} {'unlocks':>7} {'KB':>6} {'clean':>6}")
for m,g,s,c in order:
    print(f"{mods[m]:70s} {g:7d} {s//1024:6d} {c:6d}")
