import os,re
CANON_RE = re.compile(r"/-\n(Copyright[^\n]*\n)(Released[^\n]*\n)?(Authors:[^\n]*\n)?-/")
bad=[]; ok=0; shift={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in sorted(fns):
        if not fn.endswith('.lean'): continue
        p=os.path.join(dp,fn)
        t=open(p,encoding='utf-8').read()
        m=CANON_RE.match(t)
        if m:
            ok+=1
            old=m.group(0).count('\n')+1
            if old!=5: shift[p]=5-old
        else:
            bad.append((p, t.split('\n')[0][:60]))
print('matched:',ok,'unmatched:',len(bad))
for p,first in bad: print('  UNMATCHED',p,'|first line:',repr(first))
print('files whose line numbers shift:')
for p,d in shift.items(): print(f'   {d:+d}  {p}')
